def build_dpr_lines(level_index):
    bonus, sneak_dice, one_attack, two_attacks = LEVEL_DPR[level_index]
    one = f"Одна атака: Кинджал 1к4{bonus} з +{sneak_dice} Підступної атаки (DPR {one_attack})"
    two = f"Бій двома зброями: Кинджал 1к4{bonus} і Кинджал 1к4 з +{sneak_dice} Підступної атаки (DPR {two_attacks})"
    return one + "\n" + two


